import React, { useEffect, useState } from 'react';
import api from '../api/axios';
import '../styles/formation.css';

const Formation = () => {
    const [trainings, setTrainings] = useState([]);
    const [trainers, setTrainers] = useState([]);
    const [participants, setParticipants] = useState([]);
    const [showModal, setShowModal] = useState(false);
    const [showParticipantModal, setShowParticipantModal] = useState(false);
    const [showViewParticipantsModal, setShowViewParticipantsModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [selectedTraining, setSelectedTraining] = useState(null);
    const [selectedParticipants, setSelectedParticipants] = useState([]);
    const [formData, setFormData] = useState({
        title: '',
        theme: '',
        location: '',
        startDate: '',
        endDate: '',
        trainer: { id: 1 },
        participants: []
    });

    useEffect(() => {
        fetchTrainings();
        fetchTrainers();
        fetchParticipants();
    }, []);

    const fetchTrainings = async () => {
        try {
            const response = await api.get('/rh/trainings');
            setTrainings(response.data);
        } catch (error) {
            console.error('Error fetching trainings:', error);
        }
    };

    const fetchTrainers = async () => {
        try {
            const response = await api.get('/auth/users/formateurs');
            setTrainers(response.data);
        } catch (error) {
            console.error('Error fetching trainers:', error);
        }
    };

    const fetchParticipants = async () => {
        try {
            const response = await api.get('/auth/users/participants');
            setParticipants(response.data);
        } catch (error) {
            console.error('Error fetching participants:', error);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await api.post('/rh/trainings', formData);
            setShowModal(false);
            setFormData({
                title: '',
                theme: '',
                location: '',
                startDate: '',
                endDate: '',
                trainer: { id: 1 },
                participants: []
            });
            fetchTrainings();
        } catch (error) {
            console.error('Error creating training:', error);
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        if (name === 'trainer') {
            setFormData(prev => ({
                ...prev,
                trainer: { id: parseInt(value) }
            }));
        } else {
            setFormData(prev => ({
                ...prev,
                [name]: value
            }));
        }
    };

    const handleAddParticipant = (training) => {
        setSelectedTraining(training);
        setSelectedParticipants([]);
        setShowParticipantModal(true);
    };

    const handleViewParticipants = (training) => {
        setSelectedTraining(training);
        setShowViewParticipantsModal(true);
    };

    const handleParticipantSubmit = async (e) => {
        e.preventDefault();

        try {
            await api.post(`/training/${selectedTraining.id}/participants`, selectedParticipants);
            setShowParticipantModal(false);
            setSelectedTraining(null);
            setSelectedParticipants([]);
            fetchTrainings();
        } catch (error) {
            console.error('Error adding participants:', error);
        }
    };

    const handleParticipantChange = (participantId) => {
        setSelectedParticipants(prev => {
            if (prev.includes(participantId)) {
                return prev.filter(id => id !== participantId);
            } else {
                return [...prev, participantId];
            }
        });
    };

    const handleDeleteTraining = (training) => {
        setSelectedTraining(training);
        setShowDeleteModal(true);
    };

    const handleEditTraining = (training) => {
        setSelectedTraining(training);

        // Gestion robuste des dates
        const formatDateTimeLocal = (dateString) => {
            if (!dateString) return '';
            try {
                const date = new Date(dateString);
                if (isNaN(date.getTime())) return '';
                return date.toISOString().slice(0, 16);
            } catch (error) {
                return '';
            }
        };

        setFormData({
            title: training.title || '',
            theme: training.theme || '',
            location: training.location || '',
            startDate: formatDateTimeLocal(training.startDate),
            endDate: formatDateTimeLocal(training.endDate),
            trainer: training.trainer ? { id: training.trainer.id } : { id: 1 },
            participants: training.participants || []
        });
        setShowEditModal(true);
    };

    const handleUpdateTraining = async (e) => {
        e.preventDefault();
        try {
            console.log('Updating training ID:', selectedTraining.id);
            console.log('Update data:', formData);

            await api.put(`/training/${selectedTraining.id}`, formData);

            setShowEditModal(false);
            setSelectedTraining(null);
            setFormData({
                title: '',
                theme: '',
                location: '',
                startDate: '',
                endDate: '',
                trainer: { id: 1 },
                participants: []
            });
            fetchTrainings();
        } catch (error) {
            console.error('Error updating training:', error);
            console.error('Error response:', error.response);

            if (error.response?.status === 403) {
                alert('Erreur 403: Vous n\'avez pas les permissions pour modifier cette formation.');
            } else if (error.response?.status === 401) {
                alert('Erreur 401: Votre session a expiré. Veuillez vous reconnecter.');
            } else if (error.response?.status === 404) {
                alert('Erreur 404: Formation non trouvée.');
            } else {
                alert(`Erreur lors de la modification: ${error.response?.data?.error || error.message}`);
            }
        }
    };

    const handleConfirmDelete = async () => {
        try {
            const token = localStorage.getItem('token');
            console.log('Token:', token); // Debug token
            console.log('Deleting training ID:', selectedTraining.id); // Debug ID

            await api.delete(`/training/${selectedTraining.id}`);

            setShowDeleteModal(false);
            setSelectedTraining(null);
            fetchTrainings();
        } catch (error) {
            console.error('Error deleting training:', error);
            console.error('Error response:', error.response); // Debug response

            if (error.response?.status === 403) {
                alert('Erreur 403: Vous n\'avez pas les permissions pour supprimer une formation. Vérifiez que vous êtes bien connecté avec un compte autorisé.');
            } else if (error.response?.status === 401) {
                alert('Erreur 401: Votre session a expiré. Veuillez vous reconnecter.');
            } else if (error.response?.status === 404) {
                alert('Erreur 404: Formation non trouvée.');
            } else {
                alert(`Erreur lors de la suppression: ${error.response?.data?.error || error.message}`);
            }
        }
    };

    const handleRemoveParticipant = async (trainingId, participantId) => {
        try {
            const token = localStorage.getItem('token');
            console.log('Token:', token);
            console.log('Removing participant:', participantId, 'from training:', trainingId);

            await api.delete(`/training/${trainingId}/participants/${participantId}`);

            // Rafraîchir les données
            fetchTrainings();
            // Mettre à jour la formation sélectionnée si la modal est ouverte
            if (selectedTraining && selectedTraining.id === trainingId) {
                setSelectedTraining(prev => ({
                    ...prev,
                    participants: prev.participants.filter(p => p.id !== participantId)
                }));
            }
        } catch (error) {
            console.error('Error removing participant:', error);
            console.error('Error response:', error.response);

            if (error.response?.status === 403) {
                alert('Erreur 403: Vous n\'avez pas les permissions pour supprimer ce participant.');
            } else if (error.response?.status === 401) {
                alert('Erreur 401: Votre session a expiré. Veuillez vous reconnecter.');
            } else if (error.response?.status === 404) {
                alert('Erreur 404: Participant ou formation non trouvé.');
            } else {
                alert(`Erreur lors de la suppression du participant: ${error.response?.data?.error || error.message}`);
            }
        }
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Gestion des Formations</h1>
                    <p className="text-gray-600 mt-2">Gérez toutes les formations de la plateforme</p>
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
                >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                    </svg>
                    Nouvelle Formation
                </button>
            </div>

                {/* Formations Grid */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 p-4">
                    {trainings.map((training) => (
                        <div 
                            key={training.id} 
                            className="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors cursor-pointer"
                            onClick={() => handleViewParticipants(training)}
                        >
                            <div className="space-y-3">
                                <div className="flex items-start justify-between">
                                    <h3 className="text-lg font-semibold text-gray-900">{training.title}</h3>
                                    <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                                        Actif
                                    </span>
                                </div>

                                <div className="space-y-2">
                                    <div className="flex items-center text-sm text-gray-600">
                                        <svg className="w-4 h-4 mr-2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
                                        </svg>
                                        {training.theme}
                                    </div>

                                    <div className="flex items-center text-sm text-gray-600">
                                        <svg className="w-4 h-4 mr-2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                                        </svg>
                                        {training.location}
                                    </div>

                                    <div className="flex items-center text-sm text-gray-600">
                                        <svg className="w-4 h-4 mr-2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                                        </svg>
                                        {trainers.find(t => t.id === training.trainer?.id)?.fullName || 'Non assigné'}
                                    </div>
                                </div>

                                <div className="flex gap-2 pt-2">
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleAddParticipant(training);
                                        }}
                                        className="flex-1 bg-blue-600 text-white px-3 py-2 rounded text-sm hover:bg-blue-700 transition-colors"
                                    >
                                        Participants
                                    </button>

                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleEditTraining(training);
                                        }}
                                        className="flex-1 bg-gray-600 text-white px-3 py-2 rounded text-sm hover:bg-gray-700 transition-colors"
                                    >
                                        Modifier
                                    </button>

                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleDeleteTraining(training);
                                        }}
                                        className="flex-1 bg-red-600 text-white px-3 py-2 rounded text-sm hover:bg-red-700 transition-colors"
                                    >
                                        Supprimer
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {trainings.length === 0 && (
                    <div className="text-center py-12">
                        <svg className="w-16 h-16 mx-auto text-gray-300 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                        </svg>
                        <p className="text-gray-500">
                            Aucune formation disponible
                        </p>
                    </div>
                )}
            </div>

            {/* Edit Formation Modal */}
            {showEditModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg p-6 w-full max-w-md">
                        <h2 className="text-xl font-bold mb-4">Modifier la Formation</h2>
                        <form onSubmit={handleUpdateTraining} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Titre
                                </label>
                                <input
                                    type="text"
                                    name="title"
                                    value={formData.title}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Thème
                                </label>
                                <input
                                    type="text"
                                    name="theme"
                                    value={formData.theme}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Lieu
                                </label>
                                <input
                                    type="text"
                                    name="location"
                                    value={formData.location}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">
                                        Date de début
                                    </label>
                                    <input
                                        type="datetime-local"
                                        name="startDate"
                                        value={formData.startDate}
                                        onChange={handleChange}
                                        required
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">
                                        Date de fin
                                    </label>
                                    <input
                                        type="datetime-local"
                                        name="endDate"
                                        value={formData.endDate}
                                        onChange={handleChange}
                                        required
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Formateur
                                </label>
                                <select
                                    name="trainer"
                                    value={formData.trainer.id}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                >
                                    <option value="">Sélectionner un formateur</option>
                                    {trainers.map(trainer => (
                                        <option key={trainer.id} value={trainer.id}>
                                            {trainer.fullName}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <div className="flex gap-2 mt-6">
                                <button
                                    type="submit"
                                    className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
                                >
                                    Mettre à jour
                                </button>
                                <button
                                    type="button"
                                    onClick={() => {
                                        setShowEditModal(false);
                                        setSelectedTraining(null);
                                        setFormData({
                                            title: '',
                                            theme: '',
                                            location: '',
                                            startDate: '',
                                            endDate: '',
                                            trainer: { id: 1 },
                                            participants: []
                                        });
                                    }}
                                    className="flex-1 bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300 transition-colors"
                                >
                                    Annuler
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Delete Confirmation Modal */}
            {showDeleteModal && selectedTraining && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg p-6 w-full max-w-md">
                        <h2 className="text-xl font-bold mb-4">Supprimer la Formation</h2>
                        <p className="text-gray-600 mb-4">
                            Êtes-vous sûr de vouloir supprimer "{selectedTraining.title}" ?
                        </p>
                        <p className="text-sm text-red-600 mb-6">
                            Cette action est irréversible.
                        </p>
                        <div className="flex gap-2">
                            <button
                                onClick={handleConfirmDelete}
                                className="flex-1 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 transition-colors"
                            >
                                Supprimer
                            </button>
                            <button
                                onClick={() => {
                                    setShowDeleteModal(false);
                                    setSelectedTraining(null);
                                }}
                                className="flex-1 bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300 transition-colors"
                            >
                                Annuler
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Add Formation Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg p-6 w-full max-w-md">
                        <h2 className="text-xl font-bold mb-4">Nouvelle Formation</h2>
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Titre
                                </label>
                                <input
                                    type="text"
                                    name="title"
                                    value={formData.title}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Thème
                                </label>
                                <input
                                    type="text"
                                    name="theme"
                                    value={formData.theme}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Lieu
                                </label>
                                <input
                                    type="text"
                                    name="location"
                                    value={formData.location}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">
                                        Date de début
                                    </label>
                                    <input
                                        type="datetime-local"
                                        name="startDate"
                                        value={formData.startDate}
                                        onChange={handleChange}
                                        required
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">
                                        Date de fin
                                    </label>
                                    <input
                                        type="datetime-local"
                                        name="endDate"
                                        value={formData.endDate}
                                        onChange={handleChange}
                                        required
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Formateur
                                </label>
                                <select
                                    name="trainer"
                                    value={formData.trainer.id}
                                    onChange={handleChange}
                                    required
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                >
                                    <option value="">Sélectionner un formateur</option>
                                    {trainers.map(trainer => (
                                        <option key={trainer.id} value={trainer.id}>
                                            {trainer.fullName}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <div className="flex gap-2 mt-6">
                                <button
                                    type="submit"
                                    className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
                                >
                                    Créer
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setShowModal(false)}
                                    className="flex-1 bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300 transition-colors"
                                >
                                    Annuler
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Add Participants Modal */}
            {showParticipantModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[80vh] overflow-y-auto">
                        <h2 className="text-xl font-bold mb-4">Gérer les Participants</h2>
                        <p className="text-gray-600 mb-4">Formation: {selectedTraining?.title}</p>

                        <form onSubmit={handleParticipantSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Sélectionner les participants
                                </label>
                                <div className="max-h-60 overflow-y-auto border border-gray-200 rounded-lg p-2 space-y-2">
                                    {participants.map((participant) => (
                                        <div key={participant.id} className="flex items-center p-2 hover:bg-gray-50 rounded">
                                            <input
                                                type="checkbox"
                                                id={`participant-${participant.id}`}
                                                value={participant.id}
                                                checked={selectedParticipants.includes(participant.id)}
                                                onChange={() => handleParticipantChange(participant.id)}
                                                className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                                            />
                                            <label 
                                                htmlFor={`participant-${participant.id}`}
                                                className="ml-3 flex-1 cursor-pointer flex items-center"
                                            >
                                                <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center mr-3">
                                                    <span className="text-xs font-medium">
                                                        {participant.fullName.split(' ').map(n => n[0]).join('').toUpperCase()}
                                                    </span>
                                                </div>
                                                <div>
                                                    <p className="text-sm font-medium text-gray-900">{participant.fullName}</p>
                                                    <p className="text-xs text-gray-500">Participant</p>
                                                </div>
                                            </label>
                                        </div>
                                    ))}
                                    {participants.length === 0 && (
                                        <div className="text-center py-8">
                                            <p className="text-gray-500">Aucun participant disponible</p>
                                        </div>
                                    )}
                                </div>
                                {selectedParticipants.length > 0 && (
                                    <p className="text-sm text-blue-600 mt-2">
                                        {selectedParticipants.length} participant{selectedParticipants.length > 1 ? 's' : ''} sélectionné{selectedParticipants.length > 1 ? 's' : ''}
                                    </p>
                                )}
                            </div>

                            <div className="flex gap-2">
                                <button
                                    type="submit"
                                    disabled={selectedParticipants.length === 0}
                                    className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    Ajouter ({selectedParticipants.length})
                                </button>
                                <button
                                    type="button"
                                    onClick={() => {
                                        setShowParticipantModal(false);
                                        setSelectedTraining(null);
                                        setSelectedParticipants([]);
                                    }}
                                    className="flex-1 bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300 transition-colors"
                                >
                                    Annuler
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

                {/* View Participants Modal */}
            {showViewParticipantsModal && selectedTraining && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[80vh] overflow-y-auto">
                        <h2 className="text-xl font-bold mb-4">Participants de la Formation</h2>
                        <p className="text-gray-600 mb-4">{selectedTraining.title}</p>

                        <div className="grid grid-cols-2 gap-4 mb-6">
                            <div className="bg-gray-50 p-3 rounded">
                                <p className="text-xs text-gray-500 mb-1">Thème</p>
                                <p className="text-sm font-medium">{selectedTraining.theme}</p>
                            </div>
                            <div className="bg-gray-50 p-3 rounded">
                                <p className="text-xs text-gray-500 mb-1">Lieu</p>
                                <p className="text-sm font-medium">{selectedTraining.location}</p>
                            </div>
                        </div>

                        <div>
                            <h3 className="text-lg font-semibold mb-3">
                                Participants ({selectedTraining.participants?.length || 0})
                            </h3>
                            <div className="max-h-60 overflow-y-auto border border-gray-200 rounded-lg p-2 space-y-2">
                                {selectedTraining.participants && selectedTraining.participants.length > 0 ? (
                                    selectedTraining.participants.map((participant) => (
                                        <div key={participant.id} className="flex items-center p-2 bg-gray-50 rounded">
                                            <div className="w-8 h-8 bg-gray-200 rounded-full flex items-center justify-center mr-3">
                                                <span className="text-xs font-medium">
                                                    {participant.username ? participant.username.split(' ').map(n => n[0]).join('').toUpperCase() : 'U'}
                                                </span>
                                            </div>
                                            <div className="flex-1">
                                                <p className="text-sm font-medium">{participant.username}</p>
                                                <p className="text-xs text-gray-500">{participant.role.toLowerCase()}</p>
                                            </div>
                                            <button
                                                onClick={() => {
                                                    if (window.confirm(`Êtes-vous sûr de vouloir supprimer ${participant.username} de cette formation ?`)) {
                                                        handleRemoveParticipant(selectedTraining.id, participant.id);
                                                    }
                                                }}
                                                className="text-red-600 hover:text-red-800 text-sm"
                                            >
                                                Supprimer
                                            </button>
                                        </div>
                                    ))
                                ) : (
                                    <div className="text-center py-8">
                                        <p className="text-gray-500">Aucun participant</p>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="mt-6">
                            <button
                                onClick={() => {
                                    setShowViewParticipantsModal(false);
                                    setSelectedTraining(null);
                                }}
                                className="w-full bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300 transition-colors"
                            >
                                Fermer
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Formation;
